use rig::cassette::agent::AgentReplayExt;
use rig::cassette::effect_log::EffectLogRecorder;
use rig::providers::openai::{self, OpenAI};


let recorder = EffectLogRecorder::new();
let agent = AgentBuilder::new(OpenAI::from_env()?.completion(openai::GPT_5_5))
    .preamble("You are a helpful assistant.")
    .record_to(recorder.clone())
    .build();


let response = agent.prompt("Name three Rust web frameworks.").await?;
println!("{}", response.output());


let log = agent.stamp(recorder.take());
std::fs::write("frameworks.effects.json", serde_json::to_string_pretty(&log)?)?;

use rig::bus::Bus;
use rig::cassette::agent::replay::register_all;
use rig::cassette::effect_log::EffectLog;


let log: EffectLog = serde_json::from_str(&std::fs::read_to_string("frameworks.effects.json")?)?;


// A bus whose handlers are the log's replayers.
let (dispatcher, registrar, mut driver) = Bus::channel();
register_all(&log, &mut driver)?;
tokio::spawn(driver);


// The same agent, sending its model calls to the recorded model key.
let model_key = log[0].key.clone();
let agent = AgentBuilder::over_bus(dispatcher, registrar, "replay", model_key)
    .preamble("You are a helpful assistant.")
    .build();


let response = agent.prompt("Name three Rust web frameworks.").await?;
println!("{}", response.output()); // the recorded answer, no provider called

use rig::cassette::effect_log::EffectLogReplayer;
use rig::effect::EffectFamily;
use rig::tool::server::ToolServer;
use rig::tool::RegisteredTool;


let tools = ToolServer::new().run();
if let Some(record) = log.iter().find(|r| r.kind.family() == EffectFamily::Tool) {
    let replayer = EffectLogReplayer::for_key(&log, &record.key)?;
    tools.add_registered_tool(RegisteredTool::from_handler(replayer)?);
}


let agent = AgentBuilder::over_bus(dispatcher, registrar, "replay", model_key)
    .tool_server_handle(tools)
    .build();
